package com.gameaggregator.contractservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.contractservice.api.ContractDtos.*;import com.gameaggregator.contractservice.domain.*;import com.gameaggregator.contractservice.infrastructure.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class ContractService{final ContractRepository contracts;final ContractPartyRepository parties;final ContractVersionRepository versions;public ContractService(ContractRepository c,ContractPartyRepository p,ContractVersionRepository v){contracts=c;parties=p;versions=v;}public Contract create(Create r){return contracts.save(new Contract(r.contractNumber(),r.createdBy()));}public Contract get(UUID id){return contracts.findById(id).orElseThrow(()->new NotFoundException("CONTRACT_NOT_FOUND","Contract was not found"));}public List<Contract> list(){return contracts.findAll();}public ContractParty party(UUID id,Party r){get(id);return parties.save(new ContractParty(id,r.partyId(),r.partyType(),r.role()));}public ContractVersion version(UUID id,Version r){var c=get(id);if("TERMINATED".equals(c.status))throw new IllegalStateException("Terminated contract cannot be renewed");if(r.expirationDate()!=null&&r.expirationDate().isBefore(r.effectiveDate()))throw new IllegalArgumentException("Expiration date precedes effective date");int next=versions.findAllByContractIdOrderByVersionNumberDesc(id).stream().findFirst().map(v->v.versionNumber+1).orElse(1);return versions.save(new ContractVersion(id,next,r.effectiveDate(),r.expirationDate(),r.territoriesJson(),r.gameRightsJson(),r.revenueAgreementJson(),r.attachmentKey()));}public ContractVersion approve(UUID id,Approval r){var v=versions.findById(id).orElseThrow(()->new NotFoundException("CONTRACT_VERSION_NOT_FOUND","Contract version was not found"));if(!"DRAFT".equals(v.status))throw new IllegalStateException("Only draft version can be approved");v.status="APPROVED";v.approvedBy=r.actorId();var c=get(v.contractId);c.status="ACTIVE";return v;}public Contract terminate(UUID id,Termination r){var c=get(id);c.status="TERMINATED";c.terminatedAt=Instant.now();c.terminationReason=r.reason();return c;}public List<ContractVersion> versions(UUID id){get(id);return versions.findAllByContractIdOrderByVersionNumberDesc(id);}public List<ContractParty> parties(UUID id){get(id);return parties.findAllByContractId(id);}}